2	  {
3	    "verse_id": "5.2.1",
4	    "sarga": 2,
5	    "verse": "1",
6	    "ambiguous_marker": false,
7	    "sanskrit_iast": "sa sāgaram anādhṛṣyam atikramya mahābalaḥ । trikūṭasya taṭe laṅkāṃ sthitaḥ svastho dadarśa ha ॥1॥",
8	    "leonov_ru": "Тот могучий (Хануман), преодолев неодолимый океан, Стоя спокойно на склоне [горы] Трикуты, увидел [город] Ланку.",
9	    "commentary": {
10	      "tilaka": "त्रिकूटस्य लम्बापरपर्यायस्य पर्वतस्य तटे स्थितः स्वस्थो भूत्वा लङ्कां ददर्श",
11	      "bhusana": "स सागरमनाधृष्यमतिक्रम्य महाबलः ।\n\nत्रिकूटशिखरे लङ्कां स्थितां स्वस्थो ददर्श ह\nस सागरमित्यादि ।। 5.1.1,2,3।।\n\nशतान्यहं योजनानां क्रमेयं सुबहून्यपि ।\n\nकिं पुनः सागरस्यान्तं सङ्ख्यातं शतयोजनम्",
12	      "siromani": "तीर्णसागरस्य हनुमतो वृत्तान्तमेवाह स इत्यादिभिः । अनाधृष्यं धर्षयितुमशक्यं सागरं स हनूमान् अतिक्रम्य त्रिकूटस्य गिरिवर्याभिधस्य तटे स्वस्थः स्थितः सन् लङ्कां ददर्श"
13	    },
14	    "pratika_check": {
15	      "tilaka": {
16	        "pratika_iast": "trikutasya lanbaparaparyayasya parvatasya tate",
17	        "matches_verse": true
18	      },
19	      "bhusana": {
20	        "pratika_iast": "sa sagarananadhrsyanatikranya nahabalah",
21	        "matches_verse": true
22	      },
23	      "siromani": {
24	        "pratika_iast": "tirnasagarasya hanunato vrttantanevaha sa",
25	        "matches_verse": false,
26	        "content_containment": 0.75,
27	        "content_anchor": true
28	      }
29	    }
