31	  {
32	    "verse_id": "5.2.2",
33	    "sarga": 2,
34	    "verse": "2",
35	    "ambiguous_marker": false,
36	    "sanskrit_iast": "tataḥ pādapamuktena puṣpavarṣeṇa vīryavān । abhivṛṣṭas tatas tatra babhau puṣpamayo hariḥ ॥2॥",
37	    "leonov_ru": "Тогда отважная обезьяна, обсыпанная цветочным дождем, Облетевшим с деревьев, казалась сделанной из цветов.",
38	    "commentary": {
39	      "bhusana": "ततः पादपमुक्तेन पुष्पवर्षेण वीर्यवान् ।\n\nअभिवृष्टः स्थितस्तत्र बभौ पुष्पमयो यथा",
40	      "siromani": "तत इति । ततः तत्र स्थित्यनन्तरं पादपमुक्तेन तरुभिः त्यक्तेन पुष्पवर्षेण अभिवृष्टः ततः तस्माद्धेतोः पुष्पमयः हरिर्हनुमान् तत्र त्रिकूटतटे बभौ",
41	      "tattvadipika": "।। 1 ।।\n\nतत इति । पुष्पमयो यथा पुष्पमयकपिरिवेत्यर्थः"
42	    },
43	    "pratika_check": {
44	      "bhusana": {
45	        "pratika_iast": "tatah padapanuktena puspavarsena viryavan",
46	        "matches_verse": true
47	      },
48	      "siromani": {
49	        "pratika_iast": "tata",
50	        "matches_verse": true
51	      }
52	    }
53	  },
54	  {
55	    "verse_id": "5.2.3",
56	    "sarga": 2,
57	    "verse": "3",
58	    "ambiguous_marker": false,
59	    "sanskrit_iast": "yojanānāṃ śataṃ śrīmāṃs tīrtvāpy uttamavikramaḥ । aniḥśvasan kapis tatra na glānim adhigacchati ॥3॥",
60	    "leonov_ru": "Величественная и наделенная наивысшей мощью обезьяна, Одолев сотню йоджан, не запыхалась и не утомилась.",
61	    "commentary": {
62	      "tilaka": "अनिःश्वसञ्श्रमजश्वासरहितः । तदेवाह न ग्लानिमिति । कविवाक्यमेतत्",
63	      "bhusana": "योजनानां शतं श्रीमांस्तीर्त्वाप्युत्तमविक्रमः ।\n\nअनिश्वसन् कपिस्तत्र न ग्लानिमधिगच्छति\nसमुद्रलङ्घने कुतो ग्लानिं नाध्यगच्छदित्यत्राह शतानीति ।। 5.2.4,5।।\n\nशाद्वलानि च नीलानि गन्धवन्ति वनानि च ।\n\nगण्डवन्ति च मध्येन जगाम नगवन्ति च",
64	      "tattvadipika": "अनिश्वसन् श्रमनिबन्धनदीर्घनिश्श्वासममुञ्चन् । तत्र लङ्घननिमित्ते । नाधिगच्छति नाध्यगच्छत्"
65	    },
66	    "pratika_check": {
67	      "tilaka": {
68	        "pratika_iast": "anihsvasansranajasvasarahitah",
69	        "matches_verse": true
70	      },
71	      "bhusana": {
72	        "pratika_iast": "yojananan satan srinanstirtvapyuttanavikranah",
73	        "matches_verse": true
74	      },
75	      "tattvadipika": {
76	        "pratika_iast": "anisvasan srananibandhanadirghanissvasananuncan",
77	        "matches_verse": false,
78	        "content_containment": 0.091
