82	  {
83	    "verse_id": "5.2.4",
84	    "sarga": 2,
85	    "verse": "4",
86	    "ambiguous_marker": false,
87	    "sanskrit_iast": "śatāny ahaṃ yojanānāṃ krameyaṃ subahūny api । kiṃ punaḥ sāgarasyāntaṃ saṃkhyātaṃ śatayojanam ॥4॥",
88	    "leonov_ru": "«Я могу преодолеть даже многие сотни йоджан, Тем более [могу достичь] этого берега океана, до которого [всего] сотня йоджан!».",
89	    "commentary": {
90	      "tilaka": "अहं योजनानां बहूनि शतान्यपि क्रमेयं क्रामेयं क्रमितुं शक्तः । शतयोजनमिति सङ्ख्यातं सागरस्यान्तं परं पारं क्रामेयमिति का गणना ममेति । मन्यते स्मेति शेषः । हनुमदभिप्रायानुवादः कवेः",
91	      "siromani": "योजनानामिति । उत्तमविक्रमः कपिः हनूमान् योजनानां सुबहूनि शतानि अहं क्रमेयं क्रामेयं क्रमितुं शक्त इत्यर्थः, अतः संख्यातं बहुभिर्ज्ञातं शतयोजनपरिमितं सागरस्यान्तं सुबद्धसागरं क्रमेयं पुनरिति किं विचार्येति शेषः, अनिश्वसन् श्रमहेतुकनिश्वासरहितः सन् योजनानां शतं तीर्त्वा ऽपि तत्र तरणसमये ग्लानिं नाधिगच्छति अध्यगच्छत् प्राप्नोत् । श्लोकद्वयमेकान्वयि ।। 5.2.3,4 ।।\n\nस इति । स हनूमान् महोदधिं तीर्त्वा लङ्कां जगाम"
92	    },
93	    "pratika_check": {
94	      "tilaka": {
95	        "pratika_iast": "ahan yojananan bahuni satanyapi",
96	        "matches_verse": true
97	      },
