105	    "verse_id": "5.2.5",
106	    "sarga": 2,
107	    "verse": "5",
108	    "ambiguous_marker": false,
109	    "sanskrit_iast": "sa tu vīryavatāṃ śreṣṭhaḥ plavatām api cottamaḥ । jagāma vegavāṃl laṅkāṃ laṅghayitvā mahodadhim ॥5॥",
110	    "leonov_ru": "И он, наилучший из могучих, и наилучший из прыгающих (обезьян), Преодолев океан, направился, стремительный, в Ланку.",
111	    "commentary": {
112	      "tilaka": "जगाम लङ्काम् पर्वतशिखरादवरुह्येति शेषः",
113	      "bhusana": "स तु वीर्यवतां श्रेष्ठः प्लवतामपि चोत्तमः ।\n\nजगाम वेगवान् लङ्कां लङ्घयित्वा महोदधिम्"
114	    },
115	    "pratika_check": {
116	      "tilaka": {
117	        "pratika_iast": "jagana lankan parvatasikharadavaruhyeti sesah",
118	        "matches_verse": true
119	      },
120	      "bhusana": {
121	        "pratika_iast": "sa tu viryavatan sresthah",
122	        "matches_verse": true
123	      }
