1	[
2	  {
3	    "verse_id": "5.2.11",
4	    "sarga": 2,
5	    "verse": "11",
6	    "ambiguous_marker": false,
7	    "sanskrit_iast": "puṣpabhāranibaddhāṃś ca tathā mukulitān api । pādapān vihagākīrṇān pavanādhūtamastakān ॥11॥",
8	    "leonov_ru": "Деревья под ношей цветов и [еще не распустившихся] бутонов, Изобилующие птицами, с верхушками, которые качал ветер,",
9	    "commentary": {
10	      "bhusana": "पुष्पभारनिबद्धांश्च तथा मुकुलितानपि ।\n\nपादपान् विहगाकीर्णान् पवनाधूतमस्तकान्"
11	    },
12	    "pratika_check": {
13	      "bhusana": {
14	        "pratika_iast": "puspabharanibaddhansca tatha nukulitanapi",
15	        "matches_verse": true
16	      }
17	    }
18	  },
19	  {
20	    "verse_id": "5.2.12",
21	    "sarga": 2,
22	    "verse": "12",
23	    "ambiguous_marker": false,
24	    "sanskrit_iast": "haṃsakāraṇḍavākīrṇā vāpīḥ padmotpalāvṛtāḥ । ākrīḍān vividhān ramyān vividhāṃś ca jalāśayān ॥12॥",
25	    "leonov_ru": "Пруды с гусями и утками, покрытые лотосами и водяными лилиями, Разнообразные прекрасные сады и разнообразные пруды,",
